// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool _payRoyalties) public {
        vm.expectEmit(true, true, true, true);
        emit C.Initialize(
            address(0x1),
            address(0x2),
            1,
            1,
            1,
            1,
            bytes32(0),
            false,
            _payRoyalties
        );
        c.initialize(
            address(0x1),
            address(0x2),
            1,
            1,
            1,
            1,
            bytes32(0),
            false,
            _payRoyalties
        );
        assertTrue(c.payRoyalties() == _payRoyalties);
    }
}
